-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle applies migrations transactionally, so CONCURRENTLY is unavailable. This single index build supports company/agent completion-order keyset pages (at most 1024 rows), replacing repeated history sorts; it has no data backfill. Deploy during a maintenance window because the build holds a write-blocking table lock.
CREATE INDEX "heartbeat_runs_company_agent_finished_idx" ON "heartbeat_runs" USING btree ("company_id","agent_id","finished_at" DESC NULLS FIRST,"id" DESC NULLS FIRST);
